import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SafariAddressBarProps = Record<string, any>;

const LockIcon: React.FC<{ color: string }> = ({ color }) => (
  <svg 
    width="28" 
    height="28" 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke={color} 
    strokeWidth="2.5" 
    strokeLinecap="round" 
    strokeLinejoin="round"
    style={{ transition: "none" }}
  >
    <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
    <path d="M7 11V7a5 5 0 0 1 10 0v4" />
  </svg>
);

const SafariAddressBar: React.FC<SafariAddressBarProps> = ({
  backgroundColor = "#e5e5ea",
  transparentBackground = false,
  durationInSeconds = 8,
  url = "https://malloy.sg/ai-motion-designer",
  barColor = "#ffffff",
  textColor = "#111111",
  iconColor = "#8e8e93",
  cursorColor = "#007AFF",
  typingFramesPerChar = 2,
  startDelayInFrames = 30,
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Typing Logic
  const blinkRate = Math.floor(fps / 2); // 15 frames at 30fps
  const currentTypingFrame = Math.max(0, frame - startDelayInFrames);
  const charsToShow = Math.floor(currentTypingFrame / typingFramesPerChar);
  const clampedCharsToShow = Math.min(url.length, charsToShow);

  const displayedText = url.substring(0, clampedCharsToShow);

  const endTypingFrame = startDelayInFrames + (url.length * typingFramesPerChar);
  const framesSinceEnd = Math.max(0, frame - endTypingFrame);

  // Cursor Visibility Logic
  let cursorVisible = false;

  if (frame < startDelayInFrames) {
    // Blinking before typing starts
    cursorVisible = Math.floor(frame / blinkRate) % 2 === 0;
  } else if (frame >= startDelayInFrames && frame < endTypingFrame) {
    // Solid during typing
    cursorVisible = true;
  } else if (framesSinceEnd <= blinkRate * 4) {
    // Blinks twice after typing completes
    // Starts with OFF for the first interval, then ON, OFF, ON
    cursorVisible = Math.floor(framesSinceEnd / blinkRate) % 2 !== 0;
  } else {
    // Disappears completely after 2 blinks
    cursorVisible = false;
  }

  // Entrance Animation (Slide down + spring)
  const entranceProgress = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const barY = interpolate(entranceProgress, [0, 1], [-200, height * 0.12]);
  const barWidth = width * 0.88;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      <div
        style={{
          position: "absolute",
          top: barY,
          left: (width - barWidth) / 2,
          width: barWidth,
          height: 110,
          backgroundColor: barColor,
          borderRadius: 36,
          display: "flex",
          alignItems: "center",
          padding: "0 32px",
          boxSizing: "border-box",
          boxShadow: "0 10px 40px rgba(0,0,0,0.06), 0 2px 10px rgba(0,0,0,0.03)",
          transition: "none",
        }}
      >
        <LockIcon color={iconColor} />
        
        <div 
          style={{ 
            marginLeft: 20, 
            display: "flex", 
            alignItems: "center", 
            flex: 1, 
            whiteSpace: "nowrap", 
            overflow: "hidden",
            transition: "none"
          }}
        >
          <span 
            style={{ 
              color: textColor, 
              fontSize: 34, 
              fontWeight: 400, 
              letterSpacing: "-0.4px",
              lineHeight: 1,
              marginTop: 4,
              transition: "none"
            }}
          >
            {displayedText}
          </span>
          <div
            style={{
              marginLeft: 4,
              marginTop: 4,
              width: 4,
              height: 40,
              backgroundColor: cursorColor,
              opacity: cursorVisible ? 1 : 0,
              borderRadius: 2,
              transition: "none",
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SafariAddressBar;